preConditionHook:
// Brooks's sign of strength: a day that opens on its low often closes on its
// high. Stated in hindsight, it is made real-time here by comparing the
// session's opening price with the session's low SO FAR. That quantity is
// monotone -- once the open is far enough above the running low it stays
// broken for the rest of the session -- which is the wanted behaviour for a
// day-type filter.
//
// Distinct from TrendFromOpenFlag, which needs a close beyond the first bar's
// extreme; this one only needs the open to remain the session extreme.
//
// TICKS -> ATR: the source says "within a few ticks", but the engine exposes
// no tick size to a strategy (MinMove/PriceScale are chart constants only),
// so the margin is a fraction of the ATR -- the substitution
// PriorSessionLevelTest and BreakoutLevelRetest make.
//
// SESSION MODEL, per the standing decision: the twin's date > date[1],
// mirrored as day_of(ctx.Time(0)) > day_of(ctx.Time(1)).
//
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget. Seeded with a full sum on the first calculated bar or when
// the length changes, thereafter updated as TWO statements -- EL evaluates
// S[1] + in - out left to right and folding it to S += in - out rounds
// differently. One call site, in the hook, so it advances once per bar.
if (day_of(ctx.Time(0)) > day_of(ctx.Time(1))) {
    sessOpen = open[0];
    sessHigh = high[0];
    sessLow = low[0];
} else {
    if (el_gt(high[0], sessHigh)) sessHigh = high[0];
    if (el_lt(low[0], sessLow)) sessLow = low[0];
}
if (atrLen != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
nearBand = nearAtr * atr;
